export interface GeneratedPage {
  width: number;
  height: number;
  marker: string;
  oldWords?: string;
  rotation?: 0 | 90 | 180 | 270;
}
export interface GeneratedSourcePage extends GeneratedPage {
  oldWords: string;
}
export const PDF_PAGES: [GeneratedSourcePage, GeneratedSourcePage, GeneratedSourcePage] = [
  { width: 480, height: 320, marker: 'Placeholder page A', oldWords: 'A-MMMMMMMMMM' },
  { width: 320, height: 480, marker: 'Placeholder page B', oldWords: 'B-MMMMMMMMMM' },
  { width: 481.25, height: 319.5, marker: 'Placeholder page C', oldWords: 'C-MMMMMMMMMM' },
];
export function requiredAt<T>(items: readonly T[], index: number, label: string): T {
  const value = items[index];
  if (value === undefined) throw new Error(`Fixture ${label} is missing.`);
  return value;
}
const pdfString = (value: string) => `(${value.replace(/[\\()]/gu, (c) => `\\${c}`)})`;

/**
 * A hand-written searchable PDF: alternating dark strips behind the old words,
 * a generated two-color image, an asymmetric filled shape and a separate footer.
 * Pattern-only versions omit just oldWords; they are independent pixel oracles.
 */
export function generatedPdf(pages: readonly GeneratedPage[]): Buffer {
  const objects: Buffer[] = [];
  const add = (body: string | Buffer): number => {
    objects.push(Buffer.isBuffer(body) ? body : Buffer.from(body, 'latin1'));
    return objects.length;
  };
  const stream = (dictionary: string, content: string | Buffer) => {
    const data = Buffer.isBuffer(content) ? content : Buffer.from(content, 'latin1');
    return add(
      Buffer.concat([
        Buffer.from(`<< ${dictionary} /Length ${data.length} >>\nstream\n`),
        data,
        Buffer.from('\nendstream'),
      ]),
    );
  };
  add('<< /Type /Catalog /Pages 2 0 R >>');
  add('');
  const font = add('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>');
  const picture = stream(
    '/Type /XObject /Subtype /Image /Width 2 /Height 1 /ColorSpace /DeviceRGB /BitsPerComponent 8',
    Buffer.from([20, 70, 160, 210, 90, 20]),
  );
  const kids: number[] = [];
  for (const page of pages) {
    const paint: string[] = [];
    for (let x = 0; x < page.width; x += 40) {
      paint.push(
        `${(x / 40) % 2 ? '0.07 0.23 0.31' : '0.19 0.11 0.25'} rg`,
        `${x} 0 ${Math.min(40, page.width - x)} ${page.height} re f`,
      );
    }
    paint.push(`q 60 0 0 40 ${page.width - 90} ${page.height - 75} cm /Im0 Do Q`);
    paint.push(`0.7 0.15 0.1 rg 24 ${page.height - 70} 45 28 re f`);
    paint.push(`0.1 0.6 0.2 rg ${page.width - 32} 22 m ${page.width - 12} 22 l ${page.width - 12} 42 l h f`);
    if (page.oldWords)
      paint.push(`BT /F1 28 Tf 1 1 1 rg 24 ${page.height / 2} Td ${pdfString(page.oldWords)} Tj ET`);
    paint.push(`BT /F1 12 Tf 1 1 1 rg 24 24 Td ${pdfString(page.marker)} Tj ET`);
    const contents = stream('', paint.join('\n'));
    kids.push(
      add(
        `<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${page.width} ${page.height}] /Rotate ${page.rotation ?? 0} /Contents ${contents} 0 R /Resources << /Font << /F1 ${font} 0 R >> /XObject << /Im0 ${picture} 0 R >> >> >>`,
      ),
    );
  }
  objects[1] = Buffer.from(
    `<< /Type /Pages /Kids [${kids.map((id) => `${id} 0 R`).join(' ')}] /Count ${kids.length} >>`,
  );
  const parts: Buffer[] = [Buffer.from('%PDF-1.4\n')];
  const offsets: number[] = [];
  for (const [i, object] of objects.entries()) {
    offsets.push(parts.reduce((n, part) => n + part.length, 0));
    parts.push(Buffer.from(`${i + 1} 0 obj\n`), object, Buffer.from('\nendobj\n'));
  }
  const xref = parts.reduce((n, part) => n + part.length, 0);
  parts.push(
    Buffer.from(
      `xref\n0 ${objects.length + 1}\n0000000000 65535 f \n${offsets.map((offset) => `${String(offset).padStart(10, '0')} 00000 n \n`).join('')}trailer\n<< /Size ${objects.length + 1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF\n`,
    ),
  );
  return Buffer.concat(parts);
}

export async function openGeneratedPdf(pages: readonly GeneratedPage[] = PDF_PAGES) {
  const folder = mkdtempSync(join(tmpdir(), 'drashti-pdf-tools-'));
  const source = join(folder, 'Placeholder PDF tools.pdf');
  const original = generatedPdf(pages);
  writeFileSync(source, original);
  const digest = createHash('sha256').update(original).digest('hex');
  const unchanged = () => {
    const current = readFileSync(source);
    expect(current.equals(original), 'exact original generated PDF bytes').toBe(true);
    expect(createHash('sha256').update(current).digest('hex')).toBe(digest);
  };
  const { app, userData } = await launchApp({ DRASHTI_TEST_NO_CONVERTER: '1' }, undefined, {}, [
    '--force-color-profile=srgb',
  ]);
  try {
    const win = await operatorPage(app);
    await operatorReady(win);
    const [id = ''] = await importAndGetIds(win, [source]);
    expect(id, 'fixture PDF imports before any claimed feature RED').not.toBe('');
    await openLibrary(win);
    await win
      .getByTestId('presentation-list')
      .getByTestId('presentation-row')
      .filter({ hasText: 'Placeholder PDF tools' })
      .click();
    await win.getByTestId('edit-slides').click();
    const { ed, editor } = await slideEditorWindow(app);
    await sizeSlideEditor(app, ed, { width: 1280, height: 720 });
    return { app, win, ed, editor, id, userData, folder, source, original, unchanged };
  } catch (error) {
    await app.close();
    throw error;
  }
}

export async function usePdfTools(ed: Page) {
  const group = ed.getByRole('tab', { name: PDF_LABELS.group, exact: true });
  // First behavior RED after known import/editor setup; never call a made-up IPC.
  await expect(group, 'the imported PDF has its own page/mark/export tools').toBeVisible();
  await group.click();
}

export async function savePdfCopy(app: ElectronApplication, ed: Page, file: string) {
  expect(existsSync(file), 'new generated export path starts absent').toBe(false);
  await app.evaluate(({ dialog }, path) => {
    dialog.showSaveDialog = () => Promise.resolve({ canceled: false, filePath: path });
  }, file);
  const save = ed.getByRole('button', { name: PDF_LABELS.export, exact: true });
  await expect(save, 'Save a PDF copy is an actual editor action').toBeVisible();
  await save.click();
  await expect
    .poll(
      () => {
        if (!existsSync(file)) return false;
        const bytes = readFileSync(file);
        return (
          bytes.subarray(0, 5).toString('ascii') === '%PDF-' &&
          /%%EOF\s*$/u.test(bytes.subarray(-64).toString('ascii'))
        );
      },
      { message: 'a complete new PDF copy was written', timeout: 30_000 },
    )
    .toBe(true);
}
